-- Lets the editors add a player to the squad of a season in the admin (issue 1020): `players.source` and `squad_completeness.best_source` get `redactie`, the last of the list, and `persons.name_source` gets `redactie` for a name the editors filled in.
-- `persons.wikipedia_page` may be empty: a person the editors make for a player without an article has a name and no title. The unique key stays, and MariaDB lets more than one row be empty under it.
-- The log of the admin gets `player.add`, `player.edit` and `player.remove`.
-- The migration only widens: no row changes. The statements can run again: MariaDB cannot undo DDL, so a migration that stopped halfway finishes on the next start.
-- To undo it on the host, first check that no row uses what goes (`SELECT COUNT(*) FROM players WHERE source = 'redactie'`, the same for `squad_completeness.best_source` and `persons.name_source`, `SELECT COUNT(*) FROM persons WHERE wikipedia_page IS NULL`, and `SELECT COUNT(*) FROM audit_log WHERE action LIKE 'player.add' OR action LIKE 'player.edit' OR action LIKE 'player.remove'`), and only then put the four lists back as they were and make `wikipedia_page` `NOT NULL` again.
ALTER TABLE `audit_log` MODIFY COLUMN `action` enum('item.hide','item.show','item.approve','item.unapprove','article.create','article.update','article.publish','article.unpublish','match.edit','match.undo','match.caught-up','match.differs','match.take-over','match.keep','match.add','match.delete','stadium.save','stadium.reset','club-name.save','club-name.reset','player.stats-differ','player.stats-take-over','player.stats-keep','player.add','player.edit','player.remove') NOT NULL;--> statement-breakpoint
ALTER TABLE `persons` MODIFY COLUMN `wikipedia_page` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;--> statement-breakpoint
ALTER TABLE `persons` MODIFY COLUMN `name_source` enum('sort_key','guess','manual','redactie');--> statement-breakpoint
ALTER TABLE `players` MODIFY COLUMN `source` enum('selectie','statistieken','engels','transfers','doelpunten','wikidata','verslag','redactie') NOT NULL DEFAULT 'selectie';--> statement-breakpoint
ALTER TABLE `squad_completeness` MODIFY COLUMN `best_source` enum('selectie','statistieken','engels','transfers','doelpunten','wikidata','verslag','redactie') NOT NULL;